      if (!isStd(imp)) {
        if (allowed.some((m) => imp === m || imp.startsWith(m + "/"))) continue;
        bad.push(`guard: package ${dir} imports ${imp} (the standard library ${allowed.length ? "and " + allowed.join(", ") + " " : ""}only)`);
        continue;
