echo '== frozen'; git diff --quiet HEAD -- contour.yaml morph-map.json docs decks tests/fixtures go.mod go.sum internal vendor stream runner queue session eventlog telegram claude github bootstrap registry gitrules control || { echo "changed outside the targets: $(git diff --name-only HEAD -- contour.yaml morph-map.json docs decks tests/fixtures go.mod go.sum internal vendor stream runner queue session eventlog telegram claude github bootstrap registry gitrules control | tr "\n" " ")"; exit 1; }
X=$(git ls-files --others --exclude-standard | grep -vxF -e api/router_examples_test.go || true); [ -z "$X" ] || { echo "files left in the tree: $X"; exit 1; }
) > $L 2>&1; rc=$?; cat $L; exit $rc

